import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;

const TRANSITION = 15;

const COLORS = {
  orange: "#FF6B2B",
  orangeLight: "#FFB347",
  teal: "#00D4AA",
  tealDim: "#00A882",
  purple: "#9B59B6",
  blue: "#4A9EFF",
  bg: "#0E0E14",
  surface: "rgba(255,255,255,0.04)",
  border: "rgba(255,255,255,0.08)",
  text: "#FFFFFF",
  muted: "rgba(255,255,255,0.45)",
};

// ─────────────────────────────────────────────
// Scene 1: Structured data flowing into AI
// ─────────────────────────────────────────────

const DATA_ROWS = [
  { label: "title", value: "Best noise-cancelling headphones 2024" },
  { label: "views", value: "1,240,000" },
  { label: "likes", value: "48,200" },
  { label: "channel", value: "TechReviewHub" },
  { label: "published", value: "2024-03-15" },
];

const Scene1: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const containerProgress = spring({ frame, fps, delay: 5, config: { damping: 200 } });
  const arrowProgress = spring({ frame, fps, delay: 60, config: { damping: 200 } });
  const aiBoxProgress = spring({ frame, fps, delay: 75, config: { damping: 200 } });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "center",
          gap: 80,
          paddingBottom: 60,
        }}
      >
        {/* Data card */}
        <div
          style={{
            opacity: containerProgress,
            transform: `translateX(${interpolate(containerProgress, [0, 1], [-60, 0])}px)`,
            backgroundColor: COLORS.surface,
            borderRadius: 28,
            border: `1.5px solid ${COLORS.border}`,
            padding: "52px 60px",
            minWidth: 680,
          }}
        >
          <div
            style={{
              fontSize: 26,
              fontWeight: 600,
              color: COLORS.teal,
              letterSpacing: "0.12em",
              marginBottom: 36,
              textTransform: "uppercase",
            }}
          >
            Extracted Data
          </div>
          {DATA_ROWS.map((row, i) => {
            const rowProgress = spring({ frame, fps, delay: 10 + i * 12, config: { damping: 200 } });
            return (
              <div
                key={i}
                style={{
                  display: "flex",
                  flexDirection: "row",
                  gap: 24,
                  marginBottom: 20,
                  opacity: rowProgress,
                  transform: `translateY(${interpolate(rowProgress, [0, 1], [20, 0])}px)`,
                }}
              >
                <div
                  style={{
                    fontSize: 28,
                    fontWeight: 600,
                    color: COLORS.muted,
                    width: 160,
                    flexShrink: 0,
                  }}
                >
                  {row.label}
                </div>
                <div style={{ fontSize: 28, fontWeight: 500, color: COLORS.text }}>
                  {row.value}
                </div>
              </div>
            );
          })}
        </div>

        {/* Arrow */}
        <div
          style={{
            opacity: arrowProgress,
            transform: `scale(${interpolate(arrowProgress, [0, 1], [0.6, 1])})`,
            display: "flex",
            alignItems: "center",
          }}
        >
          <svg width="100" height="40" viewBox="0 0 100 40" fill="none">
            <line
              x1="0"
              y1="20"
              x2={interpolate(arrowProgress, [0, 1], [0, 80])}
              y2="20"
              stroke={COLORS.teal}
              strokeWidth="3"
              strokeLinecap="round"
            />
            <polygon points="80,10 100,20 80,30" fill={COLORS.teal} opacity={arrowProgress} />
          </svg>
        </div>

        {/* AI Box */}
        <div
          style={{
            opacity: aiBoxProgress,
            transform: `translateX(${interpolate(aiBoxProgress, [0, 1], [60, 0])}px)`,
            backgroundColor: "rgba(0,212,170,0.06)",
            borderRadius: 28,
            border: `1.5px solid rgba(0,212,170,0.3)`,
            padding: "52px 70px",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: 24,
          }}
        >
          <svg width="72" height="72" viewBox="0 0 72 72" fill="none">
            <circle cx="36" cy="36" r="30" stroke={COLORS.teal} strokeWidth="2.5" opacity={aiBoxProgress} />
            <circle cx="36" cy="36" r="10" fill={COLORS.teal} opacity={interpolate(aiBoxProgress, [0, 1], [0, 0.7])} />
            <line x1="36" y1="6" x2="36" y2="20" stroke={COLORS.teal} strokeWidth="2.5" strokeLinecap="round" opacity={aiBoxProgress} />
            <line x1="36" y1="52" x2="36" y2="66" stroke={COLORS.teal} strokeWidth="2.5" strokeLinecap="round" opacity={aiBoxProgress} />
            <line x1="6" y1="36" x2="20" y2="36" stroke={COLORS.teal} strokeWidth="2.5" strokeLinecap="round" opacity={aiBoxProgress} />
            <line x1="52" y1="36" x2="66" y2="36" stroke={COLORS.teal} strokeWidth="2.5" strokeLinecap="round" opacity={aiBoxProgress} />
          </svg>
          <div style={{ fontSize: 36, fontWeight: 700, color: COLORS.teal }}>LLM</div>
          <div style={{ fontSize: 26, color: COLORS.muted, textAlign: "center" }}>AI Analysis</div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─────────────────────────────────────────────
// Scene 2: LLM categorizing sentiment + context
// ─────────────────────────────────────────────

const VIDEO_ITEMS = [
  { title: "Best noise-cancelling headphones 2024", sentiment: "positive", context: "dedicated review" },
  { title: "My honest thoughts on this product...", sentiment: "mixed", context: "comparison" },
  { title: "This changed how I work from home", sentiment: "positive", context: "quick shoutout" },
  { title: "Don't buy until you watch this", sentiment: "negative", context: "dedicated review" },
  { title: "Top 10 picks this year", sentiment: "positive", context: "comparison" },
];

const SENTIMENT_COLORS: Record<string, string> = {
  positive: "#00D4AA",
  mixed: "#FFB347",
  negative: "#FF5C5C",
};

const CONTEXT_COLORS: Record<string, string> = {
  "dedicated review": "#4A9EFF",
  "quick shoutout": "#9B59B6",
  "comparison": "#FF6B2B",
};

const VideoItemRow: React.FC<{
  item: (typeof VIDEO_ITEMS)[number];
  delay: number;
  phaseDelay: number;
}> = ({ item, delay, phaseDelay }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const rowProgress = spring({ frame, fps, delay, config: { damping: 200 } });
  const sentimentProgress = spring({ frame, fps, delay: delay + phaseDelay, config: { damping: 200 } });
  const contextProgress = spring({ frame, fps, delay: delay + phaseDelay + 30, config: { damping: 200 } });

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "row",
        alignItems: "center",
        gap: 32,
        opacity: rowProgress,
        transform: `translateY(${interpolate(rowProgress, [0, 1], [30, 0])}px)`,
        marginBottom: 18,
      }}
    >
      <div
        style={{
          flex: 1,
          fontSize: 28,
          fontWeight: 500,
          color: COLORS.text,
          opacity: 0.85,
          whiteSpace: "nowrap",
          overflow: "hidden",
          textOverflow: "ellipsis",
        }}
      >
        {item.title}
      </div>
      <div
        style={{
          opacity: sentimentProgress,
          transform: `scale(${interpolate(sentimentProgress, [0, 1], [0.8, 1])})`,
          backgroundColor: `${SENTIMENT_COLORS[item.sentiment]}18`,
          border: `1.5px solid ${SENTIMENT_COLORS[item.sentiment]}55`,
          borderRadius: 20,
          padding: "10px 28px",
          fontSize: 22,
          fontWeight: 700,
          color: SENTIMENT_COLORS[item.sentiment],
          letterSpacing: "0.06em",
          whiteSpace: "nowrap",
        }}
      >
        {item.sentiment}
      </div>
      <div
        style={{
          opacity: contextProgress,
          transform: `scale(${interpolate(contextProgress, [0, 1], [0.8, 1])})`,
          backgroundColor: `${CONTEXT_COLORS[item.context]}18`,
          border: `1.5px solid ${CONTEXT_COLORS[item.context]}55`,
          borderRadius: 20,
          padding: "10px 28px",
          fontSize: 22,
          fontWeight: 700,
          color: CONTEXT_COLORS[item.context],
          letterSpacing: "0.04em",
          whiteSpace: "nowrap",
        }}
      >
        {item.context}
      </div>
    </div>
  );
};

const Scene2: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const headerProgress = spring({ frame, fps, delay: 5, config: { damping: 200 } });
  const colHeaderProgress = spring({ frame, fps, delay: 40, config: { damping: 200 } });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingBottom: 100,
          paddingLeft: 200,
          paddingRight: 200,
        }}
      >
        <div
          style={{
            width: "100%",
            backgroundColor: COLORS.surface,
            borderRadius: 32,
            border: `1.5px solid ${COLORS.border}`,
            padding: "60px 72px",
            opacity: headerProgress,
            transform: `translateY(${interpolate(headerProgress, [0, 1], [40, 0])}px)`,
          }}
        >
          <div
            style={{
              display: "flex",
              flexDirection: "row",
              gap: 32,
              marginBottom: 32,
              paddingBottom: 24,
              borderBottom: `1px solid ${COLORS.border}`,
              opacity: colHeaderProgress,
            }}
          >
            <div style={{ flex: 1, fontSize: 24, fontWeight: 700, color: COLORS.muted, textTransform: "uppercase", letterSpacing: "0.1em" }}>
              Video Title
            </div>
            <div style={{ width: 150, fontSize: 24, fontWeight: 700, color: COLORS.muted, textTransform: "uppercase", letterSpacing: "0.1em" }}>
              Sentiment
            </div>
            <div style={{ width: 200, fontSize: 24, fontWeight: 700, color: COLORS.muted, textTransform: "uppercase", letterSpacing: "0.1em" }}>
              Context
            </div>
          </div>
          {VIDEO_ITEMS.map((item, i) => (
            <VideoItemRow key={i} item={item} delay={20 + i * 15} phaseDelay={60} />
          ))}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─────────────────────────────────────────────
// Scene 3: Review types
// ─────────────────────────────────────────────

const REVIEW_TYPES = [
  { label: "Dedicated Review", color: "#4A9EFF", count: 47, pct: 47 },
  { label: "Quick Shoutout", color: "#9B59B6", count: 31, pct: 31 },
  { label: "Competitor Comparison", color: "#FF6B2B", count: 22, pct: 22 },
];

const Scene3: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const titleProgress = spring({ frame, fps, delay: 5, config: { damping: 200 } });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: 48,
          paddingBottom: 100,
        }}
      >
        <div
          style={{
            opacity: titleProgress,
            transform: `translateY(${interpolate(titleProgress, [0, 1], [-20, 0])}px)`,
            fontSize: 26,
            fontWeight: 700,
            color: COLORS.muted,
            letterSpacing: "0.14em",
            textTransform: "uppercase",
          }}
        >
          Mention Context
        </div>

        <div style={{ display: "flex", flexDirection: "row", gap: 56 }}>
          {REVIEW_TYPES.map((type, i) => {
            const cardProgress = spring({ frame, fps, delay: 20 + i * 20, config: { damping: 200 } });
            const barProgress = spring({ frame, fps, delay: 60 + i * 20, config: { damping: 200 } });
            const countProgress = spring({ frame, fps, delay: 65 + i * 20, config: { damping: 200 } });
            const countValue = Math.round(interpolate(countProgress, [0, 1], [0, type.count]));

            return (
              <div
                key={i}
                style={{
                  opacity: cardProgress,
                  transform: `translateY(${interpolate(cardProgress, [0, 1], [50, 0])}px)`,
                  backgroundColor: COLORS.surface,
                  borderRadius: 28,
                  border: `1.5px solid ${type.color}30`,
                  padding: "52px 64px",
                  minWidth: 380,
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  gap: 28,
                }}
              >
                <div
                  style={{
                    width: 18,
                    height: 18,
                    borderRadius: "50%",
                    backgroundColor: type.color,
                    opacity: cardProgress,
                  }}
                />
                <div
                  style={{
                    fontSize: 30,
                    fontWeight: 700,
                    color: COLORS.text,
                    textAlign: "center",
                    lineHeight: 1.3,
                  }}
                >
                  {type.label}
                </div>
                <div style={{ fontSize: 72, fontWeight: 800, color: type.color, lineHeight: 1 }}>
                  {countValue}
                  <span style={{ fontSize: 36, fontWeight: 600, color: COLORS.muted }}>%</span>
                </div>
                <div
                  style={{
                    width: "100%",
                    height: 12,
                    backgroundColor: "rgba(255,255,255,0.06)",
                    borderRadius: 6,
                    overflow: "hidden",
                  }}
                >
                  <div
                    style={{
                      width: `${type.pct * barProgress}%`,
                      height: "100%",
                      backgroundColor: type.color,
                      borderRadius: 6,
                      opacity: 0.85,
                    }}
                  />
                </div>
              </div>
            );
          })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─────────────────────────────────────────────
// Scene 4: Bulk AI tasks — clustering, pain points, keyword map
// ─────────────────────────────────────────────

const CLUSTERS = [
  { label: "Positive", color: "#00D4AA", x: -260, y: -80, count: 34 },
  { label: "Mixed", color: "#FFB347", x: 0, y: 140, count: 22 },
  { label: "Negative", color: "#FF5C5C", x: 260, y: -80, count: 14 },
];

const PAIN_POINTS = [
  { text: "Battery life too short", mentions: 28 },
  { text: "Mic quality disappoints", mentions: 21 },
  { text: "Price point too high", mentions: 17 },
  { text: "Comfort after long sessions", mentions: 14 },
];

const KEYWORDS = [
  { word: "noise-cancelling", size: 1.0, x: 0, y: 0, color: COLORS.teal },
  { word: "comfort", size: 0.62, x: -320, y: -100, color: COLORS.orangeLight },
  { word: "battery", size: 0.58, x: 310, y: -120, color: "#4A9EFF" },
  { word: "microphone", size: 0.48, x: -260, y: 130, color: "#9B59B6" },
  { word: "wireless", size: 0.44, x: 340, y: 110, color: COLORS.orange },
  { word: "premium", size: 0.38, x: 80, y: -190, color: "#00D4AA" },
  { word: "studio", size: 0.32, x: -80, y: 190, color: "#FF6B2B" },
  { word: "review", size: 0.3, x: 180, y: 200, color: COLORS.muted },
];

const Scene4: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const phaseAOpacity = interpolate(frame, [100, 120], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const phaseBOpacity = interpolate(frame, [120, 140], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const phaseBOutOpacity = interpolate(frame, [225, 245], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const phaseCOpacity = interpolate(frame, [245, 265], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const phaseBCombined = phaseBOpacity * phaseBOutOpacity;

  const labelAProgress = spring({ frame, fps, delay: 5, config: { damping: 200 } });
  const labelBProgress = spring({ frame: frame - 120, fps, delay: 5, config: { damping: 200 } });
  const labelCProgress = spring({ frame: frame - 245, fps, delay: 5, config: { damping: 200 } });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>

      {/* Phase A: Clustering */}
      <AbsoluteFill style={{ opacity: phaseAOpacity }}>
        <AbsoluteFill
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            paddingBottom: 60,
          }}
        >
          <div
            style={{
              position: "absolute",
              top: "27%",
              opacity: labelAProgress,
              transform: `translateY(${interpolate(labelAProgress, [0, 1], [-20, 0])}px)`,
              fontSize: 28,
              fontWeight: 700,
              color: COLORS.muted,
              letterSpacing: "0.12em",
              textTransform: "uppercase",
            }}
          >
            Clustering by Sentiment
          </div>

          <div style={{ position: "relative", width: 800, height: 500 }}>
            {CLUSTERS.map((cluster, i) => {
              const cp = spring({ frame, fps, delay: 15 + i * 20, config: { damping: 200 } });
              return (
                <div
                  key={i}
                  style={{
                    position: "absolute",
                    left: "50%",
                    top: "50%",
                    transform: `translate(calc(-50% + ${cluster.x * cp}px), calc(-50% + ${cluster.y * cp}px))`,
                    opacity: cp,
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    gap: 16,
                  }}
                >
                  <div
                    style={{
                      width: 140 + cluster.count * 1.5,
                      height: 140 + cluster.count * 1.5,
                      borderRadius: "50%",
                      backgroundColor: `${cluster.color}14`,
                      border: `2px solid ${cluster.color}50`,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                    }}
                  >
                    <div style={{ textAlign: "center" }}>
                      <div style={{ fontSize: 40, fontWeight: 800, color: cluster.color }}>{cluster.count}</div>
                      <div style={{ fontSize: 20, color: COLORS.muted }}>videos</div>
                    </div>
                  </div>
                  <div style={{ fontSize: 28, fontWeight: 700, color: cluster.color }}>{cluster.label}</div>
                </div>
              );
            })}
          </div>
        </AbsoluteFill>
      </AbsoluteFill>

      {/* Phase B: Pain points */}
      <AbsoluteFill style={{ opacity: phaseBCombined }}>
        <AbsoluteFill
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            gap: 40,
            paddingBottom: 80,
            paddingLeft: 300,
            paddingRight: 300,
          }}
        >
          <div
            style={{
              opacity: labelBProgress,
              transform: `translateY(${interpolate(labelBProgress, [0, 1], [-20, 0])}px)`,
              fontSize: 28,
              fontWeight: 700,
              color: COLORS.muted,
              letterSpacing: "0.12em",
              textTransform: "uppercase",
              marginBottom: 16,
            }}
          >
            Common Pain Points
          </div>

          {PAIN_POINTS.map((point, i) => {
            const rp = spring({ frame: frame - 120, fps, delay: 20 + i * 18, config: { damping: 200 } });
            const barW = spring({ frame: frame - 120, fps, delay: 40 + i * 18, config: { damping: 200 } });
            return (
              <div
                key={i}
                style={{
                  width: "100%",
                  opacity: rp,
                  transform: `translateX(${interpolate(rp, [0, 1], [-40, 0])}px)`,
                  display: "flex",
                  flexDirection: "row",
                  alignItems: "center",
                  gap: 40,
                }}
              >
                <div
                  style={{
                    width: 440,
                    flexShrink: 0,
                    fontSize: 32,
                    fontWeight: 600,
                    color: COLORS.text,
                    opacity: 0.85,
                    textAlign: "right",
                  }}
                >
                  {point.text}
                </div>
                <div
                  style={{
                    flex: 1,
                    height: 44,
                    backgroundColor: "rgba(255,255,255,0.05)",
                    borderRadius: 22,
                    overflow: "hidden",
                  }}
                >
                  <div
                    style={{
                      width: `${(point.mentions / 30) * 100 * barW}%`,
                      height: "100%",
                      background: "linear-gradient(90deg, #FF5C5C, #FF8C8C)",
                      borderRadius: 22,
                    }}
                  />
                </div>
                <div style={{ width: 80, fontSize: 32, fontWeight: 700, color: "#FF5C5C" }}>
                  {point.mentions}
                </div>
              </div>
            );
          })}
        </AbsoluteFill>
      </AbsoluteFill>

      {/* Phase C: Keyword map */}
      <AbsoluteFill style={{ opacity: phaseCOpacity }}>
        <AbsoluteFill
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            paddingBottom: 60,
          }}
        >
          <div
            style={{
              position: "absolute",
              top: "27%",
              opacity: labelCProgress,
              transform: `translateY(${interpolate(labelCProgress, [0, 1], [-20, 0])}px)`,
              fontSize: 28,
              fontWeight: 700,
              color: COLORS.muted,
              letterSpacing: "0.12em",
              textTransform: "uppercase",
            }}
          >
            Keyword Map
          </div>

          <div style={{ position: "relative", width: 900, height: 500 }}>
            {KEYWORDS.map((kw, i) => {
              const kwProgress = spring({ frame: frame - 245, fps, delay: 10 + i * 12, config: { damping: 200 } });
              return (
                <div
                  key={i}
                  style={{
                    position: "absolute",
                    left: "50%",
                    top: "50%",
                    transform: `translate(calc(-50% + ${kw.x}px), calc(-50% + ${kw.y}px)) scale(${interpolate(kwProgress, [0, 1], [0.6, 1])})`,
                    opacity: kwProgress,
                    fontSize: Math.round(28 + kw.size * 44),
                    fontWeight: kw.size > 0.7 ? 800 : 600,
                    color: kw.color,
                    whiteSpace: "nowrap",
                  }}
                >
                  {kw.word}
                </div>
              );
            })}

            <svg
              style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", overflow: "visible" }}
              viewBox="-450 -250 900 500"
            >
              {KEYWORDS.slice(1).map((kw, i) => {
                const lineProgress = spring({ frame: frame - 245, fps, delay: 25 + i * 12, config: { damping: 200 } });
                const x2 = interpolate(lineProgress, [0, 1], [0, kw.x]);
                const y2 = interpolate(lineProgress, [0, 1], [0, kw.y]);
                return (
                  <line
                    key={i}
                    x1={0}
                    y1={0}
                    x2={x2}
                    y2={y2}
                    stroke={kw.color}
                    strokeWidth="1"
                    strokeOpacity={lineProgress * 0.3}
                    strokeDasharray="4 6"
                  />
                );
              })}
            </svg>
          </div>
        </AbsoluteFill>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─────────────────────────────────────────────
// Main Composition
// ─────────────────────────────────────────────

const S1_DUR = 149;
const S2_DUR = 250;
const S3_DUR = 165;
const S4_DUR = 380;

export const durationInFrames = S1_DUR + S2_DUR + S3_DUR + S4_DUR;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={S1_DUR + TRANSITION}>
        <Scene1 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={S2_DUR + TRANSITION}>
        <Scene2 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={S3_DUR + TRANSITION}>
        <Scene3 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={S4_DUR}>
        <Scene4 />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
